SELECT accounts.customer_id, accounts.account_type, t.txn_type_list, t.refund_count FROM accounts JOIN (SELECT account_id, SORT_ARRAY(COLLECT_SET(txn_type)) AS txn_type_list, COUNT(CASE WHEN txn_type = 'REFUND' THEN 1 END) AS refund_count FROM transactions WHERE merchant <> 'Amazon' GROUP BY account_id) t ON accounts.id = t.account_id WHERE t.refund_count >= 6 ORDER BY refund_count DESC
